; Generated by nt65 from main.nt65. Do not edit.
.setcpu "65816"
.smart -
.case +
.feature at_in_identifiers -, bracket_as_indirect -, c_comments -
.feature dollar_in_identifiers -, dollar_is_pc -, force_range -, labels_without_colons -
.feature leading_dot_in_identifiers -, line_continuations -, long_jsr_jmp_rts -
.feature loose_char_term -, loose_string_term -, missing_char_term -, org_per_seg -
.feature pc_assignment -, string_escapes -, ubiquitous_idents -, underline_in_numbers -

.export main__dispatch
.export main__nmi
.export main__restore
.export main__set
.export main__table_jump
.export main__relative
.export main__far_relative
.export main__first
.export main__second
.export main__patching
.export main__enter
.export main__jumper

.import print
.import beep

.segment "BSS": absolute
cmd:        .res 1
value:      .res 1
nmi_flag:   .res 1
saved_p:    .res 1

.segment "CODE": absolute
main__dispatch:
    lda a:cmd
    asl a
    tax
    jmp (dispatch__table,x)

dispatch__table: .addr dispatch__move, dispatch__fire

dispatch__move:
    .a8
    lda #1
    rts
dispatch__fire:
    lda #2
    rts

main__nmi:
    rep #$30
    pha
    sep #$20
    lda #1
    sta a:nmi_flag
    rep #$20
    pla
    rti

main__restore:
    lda a:saved_p
    pha
    plp
    rts

main__set:
    beq set__set_two
    lda #1
    .byte $2c
set__set_two:
    lda #2
set__store:
    sta a:value
    rts

main__table_jump:
    lda a:cmd
    .a16
    and #$00ff
    asl a
    tax
    lda a:table_jump__targets,x
    pha
    rts

table_jump__targets: .addr table_jump__one - 1, table_jump__two - 1

table_jump__one:
    rts
table_jump__two:
    rts

talk:
    jsr print
    .byte $68, $65, $6c, $6c, $6f, $00  ; "hello"
    jsr beep
    .byte 10, 20
    rts

main__relative:
    per relative__back - 1
    brl talk
relative__back:
    rts

main__far_relative:
    phk
    per far_relative__back - 1
    brl far_target
far_relative__back:
    rtl

far_target:
    rtl

main__first:
    lda #$1234
    sep #$20
main__second:
    .a8
    lda #$12
    rts

main__patching:
    lda #$60
patching__op:
    sta a:$0400
    sta a:patching__op+1
    rts

main__enter:
    .a16
    lda #$1234
    sep #$20
enter__into:
    .a8
    lda #$12
    rts

main__jumper:
    jmp enter__into
